import type { Vitest } from 'vitest/node';

/**
 * Progress tracker used by {@link VitestTester} to detect a test run that has
 * become unresponsive, and to terminate it cleanly.
 *
 * ## Why this is needed
 *
 * Vitest enforces `testTimeout` with a timer that runs *inside the test worker*.
 * When a test blocks the worker's event loop with synchronous code (an infinite
 * loop, a runaway synchronous computation), that timer can never fire — so the
 * timeout never triggers and the run, and therefore `bit test`, hangs forever.
 *
 * This is a documented limitation of Vitest, not something a config option can
 * fix — JavaScript cannot interrupt synchronous execution on the same thread:
 *   - discussion: https://github.com/vitest-dev/vitest/discussions/1226
 *   - tracking issue: https://github.com/vitest-dev/vitest/issues/2920
 *   - PR https://github.com/vitest-dev/vitest/pull/6944 made the timeout win for
 *     *finite* long-synchronous tasks, but a truly infinite loop produces no
 *     result to race, so it remains unrecoverable from within the worker.
 *
 * The only way to bound such a run is to watch it from *outside* the blocked
 * worker. A reporter runs in the main orchestrator process, whose event loop is
 * NOT blocked by the stuck worker, so it can observe that no progress is being
 * made. This class records the time of the last lifecycle event; `VitestTester`
 * polls it and, once the run has been idle past the configured window, force
 * terminates via Vitest's official `Vitest.exit()` API.
 *
 * `exit()` (not `close()`) is used deliberately: `close()` awaits the stuck
 * worker and never resolves — the same failure mode reported in
 * https://github.com/angular/angular-cli/issues/32832 — whereas `exit()` tears
 * the process down via its `teardownTimeout` fallback.
 */
export class HangGuardReporter {
  private _ctx: Vitest | undefined;

  /** Wall-clock time (ms) of the most recent run-progress signal. */
  lastProgress = Date.now();

  /** The Vitest instance, captured on init so the tester can terminate it. */
  get ctx(): Vitest | undefined {
    return this._ctx;
  }

  private bump() {
    this.lastProgress = Date.now();
  }

  onInit(ctx: Vitest) {
    this._ctx = ctx;
    this.bump();
  }

  onTestRunStart() {
    this.bump();
  }

  onTestModuleQueued() {
    this.bump();
  }

  onTestModuleCollected() {
    this.bump();
  }

  onTestModuleStart() {
    this.bump();
  }

  onTestModuleEnd() {
    this.bump();
  }

  onTestCaseResult() {
    this.bump();
  }

  onUserConsoleLog() {
    this.bump();
  }

  onTestRunEnd() {
    this.bump();
  }
}
